// Arma el OBJETO JSON que recibe el Juez: query original + contexto de Airtable + contexto de herramientas + respuesta propuesta
const i = $input.first().json;
let resp; try { resp = JSON.parse(i.respuesta_agente); } catch (e) { resp = { respuesta: i.respuesta_texto }; }
let mem;  try { mem = JSON.parse(i.contexto_airtable); } catch (e) { mem = i.contexto_airtable || 'Sin historial'; }
const paquete_juez = {
  query_original: i.consulta,
  contexto_recuperado_airtable: mem,
  contexto_recuperado_herramientas: i.contexto_recuperado || 'El agente no consultó herramientas.',
  respuesta_propuesta: resp,
  criticidad: i.criticidad || 'normal',
  intento: Number(i.intento) || 0
};
return [{ json: { ...i, intento: Number(i.intento) || 0, paquete_juez, t0_juez: Date.now() } }];

