// Guardrail determinista del veredicto (la IA puntúa; el código asegura coherencia, umbral y límite de bucle)
const base = $('Armar paquete del Juez').first().json;
const j = ($input.first().json && $input.first().json.output) || {};
const ORDEN = { ACEPTADO: 0, CORREGIR: 1, RECHAZADO: 2 };
const MAX_REINTENTOS = 2;
const MODELO_JUEZ = 'google/gemini-2.5-flash';
const PRECIOS = { 'openai/gpt-4o-mini': [0.15, 0.60], 'openai/gpt-4.1-mini': [0.40, 1.60], 'google/gemini-2.5-flash': [0.30, 2.50] }; // USD por 1M tokens (in, out) – verificar en openrouter.ai/models
const SYS_JUEZ_CHARS = 3423;

const ex = Number.isInteger(j.exactitud_factual) && j.exactitud_factual >= 1 && j.exactitud_factual <= 5 ? j.exactitud_factual : null;
const estadoJuez = Object.prototype.hasOwnProperty.call(ORDEN, j.estado_veredicto) ? j.estado_veredicto : null;
const valido = ex !== null && estadoJuez !== null;
const veto = j.veto_seguridad === true;
const umbral = base.criticidad === 'alta' ? 5 : 4;      // umbral dinámico por criticidad (consigna: ACEPTADO con exactitud >= 4)

let estadoRegla;
if (!valido || veto || ex === 1) estadoRegla = 'RECHAZADO';
else if (ex >= umbral) estadoRegla = 'ACEPTADO';
else estadoRegla = 'CORREGIR';

// Se toma el veredicto MÁS CONSERVADOR entre el Juez y la regla
let estado = !valido ? 'RECHAZADO' : (ORDEN[estadoRegla] > ORDEN[estadoJuez] ? estadoRegla : estadoJuez);
let motivo = !valido ? 'salida_juez_invalida' : (estado !== estadoJuez ? 'ajuste_por_regla' : 'veredicto_juez');
if (estado === 'CORREGIR' && base.intento >= MAX_REINTENTOS) { estado = 'RECHAZADO'; motivo = 'limite_reintentos'; }

// Costo estimado del Juez (caracteres / 4)
const tIn = Math.round((SYS_JUEZ_CHARS + JSON.stringify(base.paquete_juez).length + 250) / 4);
const tOut = Math.round(JSON.stringify(j).length / 4) + 10;
const p = PRECIOS[MODELO_JUEZ] || [0, 0];
const costeJuez = (tIn * p[0] + tOut * p[1]) / 1e6;

return [{ json: {
  ...base,
  paquete_juez: undefined,
  modelo_juez: MODELO_JUEZ,
  exactitud_factual: ex,
  estado_juez: estadoJuez || 'INVALIDO',
  estado_veredicto: estado,
  motivo_estado: motivo,
  categoria_error: valido ? (j.categoria_error || 'ninguno') : 'salida_juez_invalida',
  critica: String(j.critica || 'El Juez no devolvió una salida válida.').slice(0, 500),
  veto_seguridad: veto,
  umbral,
  tokens_juez: tIn + tOut,
  coste_juez_usd: Number(costeJuez.toFixed(6)),
  coste_total_usd: Number(((Number(base.coste_ejecutor_usd) || 0) + costeJuez).toFixed(6)),
  latencia_juez_s: Number(((Date.now() - base.t0_juez) / 1000).toFixed(1))
} }];

